<?php
session_start(); require __DIR__.'/db.php'; if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$platforms=['Facebook','Instagram','TikTok','WhatsApp','YouTube'];$types=['Organic','Paid Boost','Influencer','Poster'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??''))$error='Ombi si sahihi. Jaribu tena.';
 else {
  $name=trim($_POST['campaign_name']??'');$platform=$_POST['platform']??'';$date=$_POST['post_date']??'';$time=$_POST['post_time']??'';$cost=filter_var($_POST['cost']??0,FILTER_VALIDATE_INT);$type=$_POST['type']??'';$notes=trim($_POST['notes']??'');
  if($name===''||!in_array($platform,$platforms,true)||!in_array($type,$types,true)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!preg_match('/^\d{2}:\d{2}$/',$time)||$cost===false||$cost<0)$error='Tafadhali jaza taarifa zote kwa usahihi.';
  else {$q=$pdo->prepare('INSERT INTO campaigns(campaign_name,platform,post_date,post_time,cost,type,notes) VALUES(?,?,?,?,?,?,?)');$q->execute([$name,$platform,$date,$time,$cost,$type,$notes]);header('Location:index.php');exit;}
 }
}
?><!doctype html><html lang="sw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ongeza Tangazo</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><div class="container headrow"><div><p class="eyebrow">RATIBA YA MATANGAZO</p><h1>Ongeza Tangazo</h1><p class="subhead">Panga post yako inayofuata.</p></div><a class="btn btn-light" href="index.php">← Rudi dashboard</a></div></header><main class="container form-wrap"><form method="post" class="panel form-panel"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><?php if($error):?><p class="alert-error"><?=e($error)?></p><?php endif;?><label>Jina la tangazo<input name="campaign_name" maxlength="255" required value="<?=e($_POST['campaign_name']??'')?>"></label><div class="form-grid"><label>Jukwaa<select name="platform" required><?php foreach($platforms as $p):?><option <?=($_POST['platform']??'Facebook')===$p?'selected':''?>><?=e($p)?></option><?php endforeach;?></select></label><label>Aina<select name="type" required><?php foreach($types as $t):?><option <?=($_POST['type']??'Organic')===$t?'selected':''?>><?=e($t)?></option><?php endforeach;?></select></label><label>Tarehe<input type="date" name="post_date" required value="<?=e($_POST['post_date']??date('Y-m-d'))?>"></label><label>Muda<input type="time" name="post_time" required value="<?=e($_POST['post_time']??'09:00')?>"></label><label>Gharama (TZS)<input type="number" name="cost" min="0" step="1" required value="<?=e($_POST['cost']??'0')?>"></label></div><label>Maelezo (hiari)<textarea name="notes" rows="4" maxlength="5000"><?=e($_POST['notes']??'')?></textarea></label><div class="form-actions"><button class="btn btn-primary">Hifadhi Tangazo</button><a class="btn btn-light" href="index.php">Ghairi</a></div></form></main></body></html>